#include <unordered_map>

#include <opencv2/core/persistence.hpp>

#include "rmvlpara/camera/camera.h"

namespace rm::para
{


bool CameraParam::load(const std::string &path)
{
    cv::FileStorage fs(path, cv::FileStorage::READ);
    if (!fs.isOpened())
        return false;
    cv::FileNode node;

    node = fs["EULER_0"];
    node.isNone() ? void(0) : (node >> EULER_0);
    node = fs["EULER_1"];
    node.isNone() ? void(0) : (node >> EULER_1);
    node = fs["EULER_2"];
    node.isNone() ? void(0) : (node >> EULER_2);
    node = fs["cameraMatrix"];
    node.isNone() ? void(0) : (node >> cameraMatrix);
    node = fs["distCoeffs"];
    node.isNone() ? void(0) : (node >> distCoeffs);

    return true;
}

} // rm::para
